python3 << 'EOF'
# Let me verify the D matrix construction explicitly
# For T=5, D should be (5-2)=3 rows

T = 5
D = [[0.0] * T for _ in range(T-2)]

# Row 0: [1, -2, 1, 0, 0]
for j in range(T):
    if j == 0:
        D[0][j] = 1.0
    elif j == 1:
        D[0][j] = -2.0
    elif j == 2:
        D[0][j] = 1.0
    else:
        D[0][j] = 0.0

# Row 1: [0, 1, -2, 1, 0]
for j in range(T):
    if j == 1:
        D[1][j] = 1.0
    elif j == 2:
        D[1][j] = -2.0
    elif j == 3:
        D[1][j] = 1.0
    else:
        D[1][j] = 0.0

# Row 2: [0, 0, 1, -2, 1]
for j in range(T):
    if j == 2:
        D[2][j] = 1.0
    elif j == 3:
        D[2][j] = -2.0
    elif j == 4:
        D[2][j] = 1.0
    else:
        D[2][j] = 0.0

print("D matrix (3 x 5):")
for row in D:
    print(row)

# Compute D'D
n = T
DD = [[0.0] * n for _ in range(n)]
for i in range(n):
    for j in range(n):
        for k in range(n-2):
            DD[i][j] += D[k][i] * D[k][j]

print("\nD'D matrix:")
for row in DD:
    print([f"{x:.1f}" for x in row])

# Now verify I + λ*D'D
lamb = 1
M = [[0.0] * n for _ in range(n)]
for i in range(n):
    for j in range(n):
        M[i][j] = (1.0 if i == j else 0.0) + lamb * DD[i][j]

print(f"\nI + λ*D'D (λ={lamb}):")
for row in M:
    print([f"{x:.1f}" for x in row])
EOF
